const rawInput = $input.first().json || {};
const body = rawInput.body ?? rawInput;

function cleanAttr(value) {
  return String(value ?? '').replace(/\\["ntr]/g, '').trim();
}

function tryParseJson(value) {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed) return value;
  if (!(trimmed.startsWith('{') || trimmed.startsWith('[') || trimmed.startsWith('\"') || trimmed.startsWith('\"'))) return value;
  try {
    return JSON.parse(trimmed);
  } catch {
    return value;
  }
}

function extractRawText() {
  const candidates = [];
  const visited = new Set();

  const pushIfString = (v) => {
    if (typeof v === 'string' && v.trim()) candidates.push(v);
  };

  const collect = (value, depth = 0) => {
    if (value == null || depth > 7) return;

    if (typeof value === 'string') {
      pushIfString(value);
      const parsed = tryParseJson(value);
      if (parsed !== value) collect(parsed, depth + 1);
      return;
    }

    if (typeof value !== 'object') return;
    if (visited.has(value)) return;
    visited.add(value);

    if (Array.isArray(value)) {
      for (const item of value) collect(item, depth + 1);
      return;
    }

    const preferred = ['body', 'rawBody', 'payload', 'text', 'xml', 'html', 'data', 'original_request'];
    for (const key of preferred) {
      if (Object.prototype.hasOwnProperty.call(value, key)) {
        collect(value[key], depth + 1);
      }
    }

    for (const key of Object.keys(value)) collect(value[key], depth + 1);
  };

  collect(body, 0);
  collect(rawInput, 0);
  collect(rawInput.original_request, 0);

  const scored = candidates.map((value) => {
    const text = String(value)
      .replace(/\\u003c/gi, '<')
      .replace(/\\u003e/gi, '>')
      .split('\\/').join('/');
    const score = Number(text.includes('<![CDATA[')) * 6 + Number(/<tr\b/i.test(text)) * 4 + Number(/<table\b/i.test(text)) * 3 + Number(/xjx|xajax/i.test(text));
    return { value: text, score };
  });

  scored.sort((a, b) => b.score - a.score);
  return scored.length ? scored[0].value : '';
}

function normalizeHtml(rawText) {
  const parsed = tryParseJson(rawText);
  let asText = typeof parsed === 'string' ? parsed : String(rawText || '');
  asText = asText
    .replace(/\\u003c/gi, '<')
    .replace(/\\u003e/gi, '>')
    .split('\\/').join('/');
  const cdataMatch = asText.match(/<!\[CDATA\[([\s\S]*?)\]\]>/i);
  return (cdataMatch ? cdataMatch[1] : asText).trim();
}

function parseLabelsFromTrAttributes(html) {
  const trRegex = /<tr\b([^>]*)>/gi;
  const attrRegex = /([a-zA-Z_][\w-]*)\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/g;
  const parsed = [];

  let trMatch;
  while ((trMatch = trRegex.exec(html)) !== null) {
    const attrsChunk = trMatch[1] || '';
    const row = {};

    let attrMatch;
    while ((attrMatch = attrRegex.exec(attrsChunk)) !== null) {
      const key = String(attrMatch[1] || '').toLowerCase();
      const value = attrMatch[3] ?? attrMatch[4] ?? attrMatch[5] ?? '';
      row[key] = cleanAttr(value);
    }

    if (!row.codigo) continue;

    parsed.push({
      codigo: row.codigo || '',
      contas: row.contas || '',
      boletos: row.boletos || '',
      nota: row.nota || '',
      cliente: row.cliente || '',
      status: row.status || '',
      vendedor: row.vendedor || '',
      chave: row.chave || '',
      numeronfs: row.numeronfs || '',
      notarecibo: row.notarecibo || '',
      vinculooscomnfs: row.vinculooscomnfs || '',
      runned: row.runned || '0'
    });
  }

  return parsed;
}

function parseLabelsFromCells(html) {
  const rowMatches = [...html.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];
  if (rowMatches.length <= 1) return [];

  const parsed = [];
  for (const row of rowMatches.slice(1)) {
    const cellMatches = [...row[1].matchAll(/<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/gi)];
    const cells = cellMatches.map((c) => String(c[1] || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/gi, ' ').trim());
    if (!cells.length) continue;
    const codigo = cells[0] || '';
    if (!codigo) continue;

    parsed.push({
      codigo,
      contas: cells[1] || '',
      boletos: cells[2] || '',
      nota: cells[3] || '',
      cliente: cells[4] || '',
      status: cells[5] || '',
      vendedor: cells[6] || '',
      chave: cells[7] || '',
      numeronfs: cells[8] || '',
      notarecibo: cells[9] || '',
      vinculooscomnfs: cells[10] || '',
      runned: cells[11] || '0'
    });
  }

  return parsed;
}

let labels = [];
if (body && body.data && Array.isArray(body.data.labels)) labels = body.data.labels;

if (!labels.length) {
  const rawText = extractRawText();
  const html = normalizeHtml(rawText);
  labels = parseLabelsFromTrAttributes(html);
  if (!labels.length) labels = parseLabelsFromCells(html);
}

if (!Array.isArray(labels) || labels.length === 0) {
  return {
    _valid: false,
    statusCode: 400,
    body: {
      ok: false,
      error: 'Missing or invalid labels payload (JSON or CDATA)',
      debug: {
        body_type: typeof body,
        raw_input_keys: Object.keys(rawInput || {}),
        body_keys: body && typeof body === 'object' ? Object.keys(body) : [],
        original_request_keys: rawInput.original_request && typeof rawInput.original_request === 'object' ? Object.keys(rawInput.original_request) : []
      }
    }
  };
}

console.log(JSON.stringify({ timestamp: new Date().toISOString(), route: 'nf_service_labels', event: 'input_validated', labels_count: labels.length, level: 'info' }));
return { _valid: true, labels };

const ctx = $input.first().json || {};
const labels = Array.isArray(ctx.labels) ? ctx.labels : [];

function cleanValue(value) {
  return String(value ?? '').trim();
}

const transformed = labels.map((label, index) => {
  const codigo = cleanValue(label.codigo || label.Codigo || label.codigo_servico);
  if (!codigo) {
    console.log(JSON.stringify({ timestamp: new Date().toISOString(), route: 'nf_service_labels', event: 'label_skipped_no_codigo', label_index: index, level: 'warn' }));
    return null;
  }

  return {
    codigo_servico: codigo,
    contas: cleanValue(label.contas || label.Contas),
    boletos: cleanValue(label.boletos || label.Boletos),
    nota: cleanValue(label.nota || label.Nota),
    cliente: cleanValue(label.cliente || label.Cliente),
    status: cleanValue(label.status || label.Status),
    vendedor: cleanValue(label.vendedor || label.Vendedor),
    chave: cleanValue(label.chave || label.Chave),
    numeronfs: cleanValue(label.numeronfs || label.NumeroNfs || label.NumeroNFS),
    notarecibo: cleanValue(label.notarecibo || label.NotaRecibo),
    vinculooscomnfs: cleanValue(label.vinculooscomnfs || label.VinculoOsComNfs),
    runned: cleanValue(label.runned || label.Runned || '0')
  };
}).filter(Boolean);

console.log(JSON.stringify({ timestamp: new Date().toISOString(), route: 'nf_service_labels', event: 'labels_transformed', valid_labels: transformed.length, total_input: labels.length, level: 'info' }));

return transformed;

const affectedRecords = $input.all().length;
console.log(JSON.stringify({ timestamp: new Date().toISOString(), route: 'nf_service_labels', event: 'service_labels_upserted', labels_updated: affectedRecords, level: 'info' }));
return { statusCode: 200, body: { message: 'Data extracted, cleaned, and converted to DataFrame successfully' } };

const errData = $input.first().json;
console.log(JSON.stringify({ timestamp: new Date().toISOString(), route: 'nf_service_labels', event: 'db_error', message: errData.message || 'Unknown DB error', level: 'error' }));
return { statusCode: 500, body: { ok: false, error: 'Database error', message: 'Could not update service labels' } };
